import{_ as i,o as s,c as n,ab as e}from"./chunks/framework.DQy4ijAa.js";const u=JSON.parse('{"title":"基本概念","description":"","frontmatter":{},"headers":[],"relativePath":"ai/langChain/chains.md","filePath":"ai/langChain/chains.md","lastUpdated":1773192027000}'),l={name:"ai/langChain/chains.md"};function t(h,a,p,r,o,k){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="基本概念" tabindex="-1">基本概念 <a class="header-anchor" href="#基本概念" aria-label="Permalink to &quot;基本概念&quot;">​</a></h1><p>Chain：链，用于将多个组件（提示模板、LLM模型、记忆、工具等）连接起来，形成可复用的 工作 流 ，完成复杂的任务。</p><p><strong>Chain 的核心思想</strong>是通过组合不同的模块化单元，实现比单一组件更强大的功能。比如： 将 LLM 与 Prompt Template （提示模板）结合</p><ul><li>将 LLM 与 输出解析器 结合</li><li>将 LLM 与 外部数据 结合，例如用于问答</li><li>将 LLM 与 长期记忆 结合，例如用于聊天历史记录</li><li>通过将 第一个LLM 的输出作为 第二个LLM 的输入，...，将多个LLM按顺序结合在一起</li></ul><h1 id="lcel-及其基本构成" tabindex="-1">LCEL 及其基本构成 <a class="header-anchor" href="#lcel-及其基本构成" aria-label="Permalink to &quot;LCEL 及其基本构成&quot;">​</a></h1><p>LangChain表达式语言（LCEL，LangChain Expression Language）是一种声明式方法，可以轻松地 将多个组件链接成 AI 工作流。它通过Python原生操作符（如管道符 | ）将组件连接成可执行流程，显 著简化了AI应用的开发。</p><p><strong>LCEL的基本构成</strong>：提示（Prompt）+ 模型（Model）+ 输出解析器（OutputParser）</p><p>即：</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 在这个链条中，用户输入被传递给提示模板，然后提示模板的输出被传递给模型，然后模型的输出被传</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">递给输出解析器。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">chain </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> prompt </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> output_parser</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">chain.invoke({</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;input&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;What&#39;s your name?&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ul><li><p>Prompt：Prompt 是一个 BasePromptTemplate，这意味着它接受一个模板变量的字典并生成一 个 PromptValue 。PromptValue 可以传递给 LLM（它以字符串作为输入）或 ChatModel（它以 消息序列作为输入）。</p></li><li><p>Model：将 PromptValue 传递给 model。如果我们的 model 是一个 ChatModel，这意味着它 将输出一个 BaseMessage 。</p></li><li><p>OutputParser：将 model 的输出传递给 output_parser，它是一个 BaseOutputParser，意味着 它可以接受字符串或 BaseMessage 作为输入。</p></li><li><p>chain：我们可以使用 | 运算符轻松创建这个Chain。 | 运算符在 LangChain 中用于将两个 元素组合在一起。</p></li><li><p>invoke：所有LCEL对象都实现了 Runnable 协议，保证一致的调用方式 （ invoke / batch / stream ）</p></li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>| 符号类似于 shell ⾥⾯管道操作符，它将不同的组件链接在⼀起，将前⼀个组件的输出作为下⼀ 个组件的输⼊，这就形成了⼀个 AI ⼯作流。</p></div><h1 id="runnable" tabindex="-1">Runnable <a class="header-anchor" href="#runnable" aria-label="Permalink to &quot;Runnable&quot;">​</a></h1><p>Runnable是LangChain定义的一个抽象接口（Protocol），它 <strong>强制要求</strong> 所有LCEL组件实现一组标准方 法：</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Runnable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Protocol</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">):</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> invoke</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(self, input: Any) -&gt; Any: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 单输入单输出</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> batch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(self, inputs: List[Any]) -&gt; List[Any]: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 批量处理</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> stream</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(self, input: Any) -&gt; Iterator[Any]: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 流式输出</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 还有其他方法如 ainvoke（异步）等...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>任何实现了这些方法的对象都被视为LCEL兼容组件。比如：聊天模型、提示词模板、输出解析器、检索 器、代理(智能体)等。</p><p>每个 LCEL 对象都实现了 Runnable 接口，该接口定义了一组公共的调用方法。这使得 LCEL 对象链也 自动支持这些调用成为可能。</p><h2 id="统一协议的优势" tabindex="-1">统一协议的优势 <a class="header-anchor" href="#统一协议的优势" aria-label="Permalink to &quot;统一协议的优势&quot;">​</a></h2><ul><li>一致性：无论组件的功能多复杂（模型/提示词/工具），调用方式完全相同</li><li>组合性：管道操作符 | 背后自动处理类型匹配和中间结果传递</li></ul><p>假设没有统一协议：</p><ul><li>提示词渲染用 .format()</li><li>模型调用用 .generate()</li><li>解析器解析用 .parse()</li><li>工具调用用 .run() 代码会变成：</li></ul><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">prompt_text </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> prompt.format(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">topic</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;猫&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 方法1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model_out </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> model.generate(prompt_text) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 方法2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">result </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> parser.parse(model_out) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 方法3</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>痛点：每个组件调用方式不同，组合时需要手动适配。</p><hr><h1 id="传统chain的使用" tabindex="-1">传统Chain的使用 <a class="header-anchor" href="#传统chain的使用" aria-label="Permalink to &quot;传统Chain的使用&quot;">​</a></h1><h2 id="基础链-llmchain" tabindex="-1">基础链：LLMChain <a class="header-anchor" href="#基础链-llmchain" aria-label="Permalink to &quot;基础链：LLMChain&quot;">​</a></h2><p>这个链至少包括一个提示词模板（PromptTemplate），一个语言模型（LLM 或聊天模型）。</p><blockquote><p>注意：LLMChain was deprecated in LangChain 0.1.17 and will be removed in 1.0. Use prompt | llm instead。</p></blockquote><p>特点：</p><ul><li>用于 单次问答，输入一个 Prompt，输出 LLM 的响应。</li><li>适合 无上下文 的简单任务（如翻译、摘要、分类等）。</li><li>无记忆：无法自动维护聊天历史</li></ul><h2 id="顺序链-simplesequentialchain" tabindex="-1">顺序链 (SimpleSequentialChain) <a class="header-anchor" href="#顺序链-simplesequentialchain" aria-label="Permalink to &quot;顺序链 (SimpleSequentialChain)&quot;">​</a></h2><p>顺序链（SequentialChain）允许将多个链顺序连接起来，每个Chain的输出作为下一个Chain的输入， 形成特定场景的流水线（Pipeline）。</p><p>顺序链有两种类型：</p><ul><li>单个输入/输出：对应着 SimpleSequentialChain <ul><li>SimpleSequentialChain：最简单的顺序链，多个链 <code>串联执行</code> ，每个步骤都有 <code>单一</code> 的输入和输出，一 个步骤的输出就是下一个步骤的输入，无需手动映射。</li></ul></li><li>多个输入/输出：对应着：SequentialChain <ul><li>多变量支持 ：允许不同子链有独立的输入/输出变量。</li><li>灵活映射 ：需 <strong>显式定义</strong> 变量如何从一个链传递到下一个链。即精准地命名输入关键字和输出关键 字，来明确链之间的关系。</li><li>复杂流程控制 ：支持分支、条件逻辑（分别通过 input_variables 和 output_variables 配置输入 和输出）。</li></ul></li></ul><h2 id="数学链-llmmathchain" tabindex="-1">数学链 LLMMathChain <a class="header-anchor" href="#数学链-llmmathchain" aria-label="Permalink to &quot;数学链 LLMMathChain&quot;">​</a></h2><p>LLMMathChain将用户问题转换为数学问题，然后将数学问题转换为可以使用 Python 的 numexpr 库 执行的表达式。使用运行此代码的输出来回答问题。</p><h2 id="路由链-routerchain" tabindex="-1">路由链 RouterChain <a class="header-anchor" href="#路由链-routerchain" aria-label="Permalink to &quot;路由链 RouterChain&quot;">​</a></h2><p>路由链（RouterChain）用于创建可以 <strong>动态选择下一条链</strong> 的链。可以自动分析用户的需求，然后引导到 最适合的链中执行，获取响应并返回最终结果。</p><h2 id="文档链-stuffdocumentschain" tabindex="-1">文档链 StuffDocumentsChain <a class="header-anchor" href="#文档链-stuffdocumentschain" aria-label="Permalink to &quot;文档链 StuffDocumentsChain&quot;">​</a></h2><p>StuffDocumentsChain 是一种文档处理链，它的核心作用是将 <strong>多个文档内容合并</strong> （“填充”或“塞 入”）到单个提示（prompt）中，然后传递给语言模型（LLM）进行处理。</p><p>使用场景 ：由于所有文档被完整拼接，LLM 能同时看到全部内容，所以适合需要全局理解的任务，如总 结、问答、对比分析等。但注意，仅适合处理 <strong>少量/中等长度文档</strong> 的场景。</p><h1 id="基于lcel构建的chains的类型" tabindex="-1">基于LCEL构建的Chains的类型 <a class="header-anchor" href="#基于lcel构建的chains的类型" aria-label="Permalink to &quot;基于LCEL构建的Chains的类型&quot;">​</a></h1><h2 id="create-sql-query-chain" tabindex="-1">create_sql_query_chain <a class="header-anchor" href="#create-sql-query-chain" aria-label="Permalink to &quot;create_sql_query_chain&quot;">​</a></h2><p>create_sql_query_chain，SQL查询链，是创建生成SQL查询的链，用于将 <strong>自然语言</strong> 转换成 <strong>数据库的 SQL查询</strong></p><h2 id="create-stuff-documents-chain" tabindex="-1">create_stuff_documents_chain <a class="header-anchor" href="#create-stuff-documents-chain" aria-label="Permalink to &quot;create_stuff_documents_chain&quot;">​</a></h2><p>create_stuff_documents_chain用于将 <strong>多个文档内容</strong> 合并成 <strong>单个长文本</strong> 的链式工具，并一次性传递给 LLM处理（而不是分多次处理）。</p><p>适合场景：</p><ul><li>保持上下文完整，适合需要全局理解所有文档内容的任务（如总结、问答）</li><li>适合处理 <strong>少量/中等长度文档</strong> 的场景</li></ul>`,47)])])}const c=i(l,[["render",t]]);export{u as __pageData,c as default};
